request.description:
### GET /server-events/10

This endpoint retrieves server events with the specified ID.

#### Request

No request body is required for this GET request.

#### Response

The response for this request follows the JSON schema below:

``` json
{
  "type": "object",
  "properties": {
    "action": {
      "type": "string"
    },
    "messages": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "id": {
            "type": "string"
          },
          "author": {
            "type": "object",
            "properties": {
              "role": {
                "type": "string"
              }
            }
          },
          "create_time": {
            "type": "number"
          },
          "content": {
            "type": "object",
            "properties": {
              "content_type": {
                "type": "string"
              },
              "parts": {
                "type": "array",
                "items": {
                  "type": "string"
                }
              }
            }
          },
          "metadata": {
            "type": "object",
            "properties": {
              "serialization_metadata": {
                "type": "object",
                "properties": {
                  "custom_symbol_offsets": {
                    "type": "array",
                    "items": {
                      "type": "integer"
                    }
                  }
                }
              },
              "dictation": {
                "type": "boolean"
              }
            }
          }
        }
      }
    },
    "conversation_id": {
      "type": "string"
    },
    "parent_message_id": {
      "type": "string"
    },
    "model": {
      "type": "string"
    },
    "timezone_offset_min": {
      "type": "number"
    },
    "timezone": {
      "type": "string"
    },
    "conversation_mode": {
      "type": "object",
      "properties": {
        "kind": {
          "type": "string"
        }
      }
    },
    "enable_message_followups": {
      "type": "boolean"
    },
    "system_hints": {
      "type": "array"
    },
    "supports_buffering": {
      "type": "boolean"
    },
    "supported_encodings": {
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "client_contextual_info": {
      "type": "object",
      "properties": {
        "is_dark_mode": {
          "type": "boolean"
        },
        "time_since_loaded": {
          "type": "number"
        },
        "page_height": {
          "type": "number"
        },
        "page_width": {
          "type": "number"
        },
        "pixel_ratio": {
          "type": "number"
        },
        "screen_height": {
          "type": "number"
        },
        "screen_width": {
          "type": "number"
        }
      }
    },
    "paragen_cot_summary_display_override": {
      "type": "string"
    }
  }
}

 ```
